        //   We want row-major  D = A * B^T  (A: MxK, B: NxK).
        //   In col-major this is D^T = B * A^T.
        //   opA=N on B (KxN col-major), opB=T on A (KxM col-major) => D^T: NxM col-major.
        cublasOperation_t transa = CUBLAS_OP_T; // applied to x (col-major KxM)
