        //   A (x, treated col-major K rows x M cols): rows=K, cols=M, ld=K
        //   B (weight, treated col-major K rows x N cols): rows=K, cols=N, ld=K
        //   C/D (output, treated col-major N rows x M cols): rows=N, cols=M, ld=N
